# 155/156: paper14, step 3. Elastic moduli: counts from symmetry, values as labels, constraints from stability and causality.
# EL1 number of independent elastic moduli of a crystal = dimension of the subspace of quadratic forms on strain (Sym^2 of the 6-dim
#     strain space, 21-dim) invariant under the point group: triclinic 21, monoclinic 13, orthorhombic 9, tetragonal 7 (C4) / 6 (D4),
#     trigonal 7 (C3) / 6 (D3), hexagonal 5, cubic 3, isotropic 2 (known counts: Nye 1957).
# EL2 label media at the unstressed background: strain directions generated by the local part of G cost nothing; the moduli are the
#     quadratic forms on the remaining strains invariant under the rigid part: fluid 1, smectic 3, columnar 4 (with the isotropic solid 2
#     and cubic 3 of EL1).
# EL3 isotropic stability K > 0, mu > 0 is equivalent to c_L^2 > 0 with 0 < c_T^2/c_L^2 < 3/4, and to mu > 0 with -1 < nu < 1/2 (sampling); tabulated sound
#     speeds of 13 isotropic materials (CRC Handbook, "Speed of sound in solids") and an auxetic foam (Lakes 1987, nu = -0.7) satisfy it;
#     causality c_L < c holds with margin ~1e-5.
# EL4 cubic Born stability C11 - C12 > 0, C11 + 2 C12 > 0, C44 > 0 holds for 11 cubic crystals (Kittel, Introduction to Solid State
#     Physics, 8th ed., ch. 3, adiabatic stiffnesses at room temperature, units 1e11 N/m^2); the values span two orders of magnitude and
#     the anisotropy ratio 2 C44/(C11 - C12) ranges from 0.37 (KCl) to 3.2 (Cu): the values are labels.
# EL5 the Cauchy relation C12 = C44 is not fixed by the symmetry: it holds within 5% for NaCl and KCl and fails by more than 15% for Cu,
#     Au, Si and MgO; it needs a further premise (central pair forces, known).
# Data are transcribed by hand from the cited tables; the checks use only inequalities and ratios of order one.
# Run: ~/.venvs/jev/bin/python ga_cont_elastic_check.py
import numpy as np

rng = np.random.default_rng(3)

def ok(name, cond):
    print(("PASS " if cond else "FAIL ") + name, flush=True)
    assert cond

# ---------- strain space and quadratic forms ----------
IDX = [(0, 0), (1, 1), (2, 2), (1, 2), (0, 2), (0, 1)]
def sym_to_vec(e): return np.array([e[i, j] * (1 if i == j else np.sqrt(2)) for i, j in IDX])
def vec_to_sym(v):
    e = np.zeros((3, 3))
    for k, (i, j) in enumerate(IDX):
        if i == j: e[i, i] = v[k]
        else: e[i, j] = e[j, i] = v[k] / np.sqrt(2)
    return e
def strain_rep(R):                                       # 6x6 action eps -> R eps R^T
    return np.array([sym_to_vec(R @ vec_to_sym(np.eye(6)[k]) @ R.T) for k in range(6)]).T
def quad_rep(D):                                         # action on symmetric 6x6 matrices Q -> D Q D^T, as 21x21
    basis = []
    for a in range(6):
        for b in range(a, 6):
            Q = np.zeros((6, 6)); Q[a, b] = Q[b, a] = 1; basis.append(Q)
    B = np.array([q[np.triu_indices(6)] for q in basis]).T
    img = np.array([(D @ q @ D.T)[np.triu_indices(6)] for q in basis]).T
    return np.linalg.lstsq(B, img, rcond=None)[0]
def n_invariant(gens, lie=False):
    rows = []
    for g in gens:
        M = quad_rep(strain_rep(g)) if not lie else None
        if lie:                                          # infinitesimal: derivative of the action
            h = 1e-6
            M = (quad_rep(strain_rep(np.eye(3) + h * g)) - np.eye(21)) / h
            rows.append(M)
        else:
            rows.append(M - np.eye(21))
    A = np.vstack(rows)
    return 21 - np.linalg.matrix_rank(A, tol=1e-4 if lie else 1e-8)

def Rz(a): c, s = np.cos(a), np.sin(a); return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])
def Rx(a): c, s = np.cos(a), np.sin(a); return np.array([[1, 0, 0], [0, c, -s], [0, s, c]])
C3d = np.array([[0, 0, 1], [1, 0, 0], [0, 1, 0]])        # threefold along [111]
groups = {'triclinic (C1)': [np.eye(3)], 'monoclinic (C2)': [Rz(np.pi)], 'orthorhombic (D2)': [Rz(np.pi), Rx(np.pi)],
          'tetragonal (C4)': [Rz(np.pi / 2)], 'tetragonal (D4)': [Rz(np.pi / 2), Rx(np.pi)],
          'trigonal (C3)': [Rz(2 * np.pi / 3)], 'trigonal (D3)': [Rz(2 * np.pi / 3), Rx(np.pi)],
          'hexagonal (C6)': [Rz(np.pi / 3)], 'hexagonal (D6)': [Rz(np.pi / 3), Rx(np.pi)],
          'cubic (T)': [C3d, Rz(np.pi)], 'cubic (O)': [C3d, Rz(np.pi / 2)]}
want = {'triclinic (C1)': 21, 'monoclinic (C2)': 13, 'orthorhombic (D2)': 9, 'tetragonal (C4)': 7, 'tetragonal (D4)': 6,
        'trigonal (C3)': 7, 'trigonal (D3)': 6, 'hexagonal (C6)': 5, 'hexagonal (D6)': 5, 'cubic (T)': 3, 'cubic (O)': 3}
got = {k: n_invariant(g) for k, g in groups.items()}
E = lambda i, j: np.eye(3)[:, [i]] @ np.eye(3)[[j], :]
so3 = [E(0, 1) - E(1, 0), E(0, 2) - E(2, 0), E(1, 2) - E(2, 1)]
got['isotropic (SO(3))'] = n_invariant(so3, lie=True); want['isotropic (SO(3))'] = 2
ok("EL1 independent elastic moduli from the point group: " + ", ".join(f"{k} {v}" for k, v in got.items()), got == want)

# ---------- EL2 label media ----------
def media_count(gauge_X, rigid_lie):
    # strains generated by the local algebra: sym(X); moduli = quadratic forms on the annihilator, invariant under the rigid part
    G = np.array([sym_to_vec((X + X.T) / 2) for X in gauge_X]) if gauge_X else np.zeros((0, 6))
    if len(G):
        _, s, vt = np.linalg.svd(G); r = int((s > 1e-10).sum()); W = vt[r:]          # functionals vanishing on gauge strains
    else:
        W = np.eye(6)
    d = W.shape[0]
    if d == 0: return 0
    # quadratic forms on W: Q = W^T S W with S symmetric d x d; invariance under rigid rotations of strain
    basis = []
    for a in range(d):
        for b in range(a, d):
            S = np.zeros((d, d)); S[a, b] = S[b, a] = 1; basis.append(W.T @ S @ W)
    if not rigid_lie: return len(basis)
    rows = []
    for g in rigid_lie:
        h = 1e-6; D = (strain_rep(np.eye(3) + h * g) - np.eye(6)) / h
        rows.append(np.array([(D.T @ Q + Q @ D)[np.triu_indices(6)] for Q in basis]).T)
    A = np.vstack(rows)
    return len(basis) - np.linalg.matrix_rank(A, tol=1e-4)
sl3 = [E(i, j) for i in range(3) for j in range(3) if i != j] + [E(0, 0) - E(1, 1), E(1, 1) - E(2, 2)]
gS = [E(0, 1), E(1, 0), E(0, 0) - E(1, 1), E(0, 2), E(1, 2)]
gC_local = [E(2, 0), E(2, 1)]
cnt = {'fluid': media_count(sl3, []), 'smectic': media_count(gS, []), 'columnar': media_count(gC_local, [E(0, 1) - E(1, 0)]),
       'isotropic solid': media_count([], so3)}
ok("EL2 moduli of label media at the unstressed background: " + ", ".join(f"{k} {v}" for k, v in cnt.items()) +
   " (fluid: bulk; smectic: bulk, layer compression, coupling; columnar: bulk, column compression, coupling, in-plane shear)",
   cnt == {'fluid': 1, 'smectic': 3, 'columnar': 4, 'isotropic solid': 2})

# ---------- EL3 isotropic stability and data ----------
viol = 0
for _ in range(20000):
    K, mu = rng.normal(size=2) * 3
    stable = K > 0 and mu > 0
    if abs(3 * K + mu) < 1e-9 or abs(K + 4 * mu / 3) < 1e-9: continue
    r2 = mu / (K + 4 * mu / 3); nu = (3 * K - 2 * mu) / (2 * (3 * K + mu))
    crit1 = K + 4 * mu / 3 > 0 and 0 < r2 < 0.75
    crit2 = mu > 0 and -1 < nu < 0.5
    viol += (stable != crit1) + (stable != crit2)
# CRC Handbook of Chemistry and Physics, "Speed of sound in solids": c_L (bulk longitudinal), c_T (shear), m/s
CRC = {'aluminium, rolled': (6420, 3040), 'copper, annealed': (4760, 2325), 'iron, electrolytic': (5950, 3240),
       'lead, annealed': (2160, 700), 'fused silica': (5968, 3764), 'Pyrex glass': (5640, 3280), 'polystyrene': (2350, 1120),
       'Lucite': (2680, 1100), 'tungsten, annealed': (5220, 2890), 'beryllium': (12890, 8880), 'stainless steel 347': (5790, 3100),
       'nickel': (6040, 3000), 'gold, hard-drawn': (3240, 1200)}
rows, good = [], True
for m, (cl, ct) in CRC.items():
    r2 = (ct / cl) ** 2; nu = (1 - 2 * r2) / (2 * (1 - r2))
    good &= r2 < 0.75 and -1 < nu < 0.5
    rows.append((m, ct / cl, nu))
nu_lakes = -0.7                                        # Lakes, Science 235 (1987) 1038, re-entrant foam
r2_lakes = (1 - 2 * nu_lakes) / (2 * (1 - nu_lakes))
c = 299792458.0
rmax = max(r for _, r, _ in rows); numin = min(n for _, _, n in rows); numax = max(n for _, _, n in rows)
ok(f"EL3 K > 0 and mu > 0 <=> (c_L^2 > 0 and 0 < c_T^2/c_L^2 < 3/4) <=> (mu > 0 and -1 < nu < 1/2): {viol} disagreements in 20000 samples; data: c_T/c_L <= {rmax:.3f} "
   f"< sqrt(3)/2 = {np.sqrt(0.75):.3f}, nu from {numin:.3f} to {numax:.3f} over 13 materials; auxetic foam nu = -0.7 gives c_T/c_L = "
   f"{np.sqrt(r2_lakes):.3f}; max c_L/c = {max(v[0] for v in CRC.values()) / c:.1e}",
   viol == 0 and good and r2_lakes < 0.75 and -1 < nu_lakes < 0.5)

# ---------- EL4 cubic Born stability, values as labels ----------
# Kittel, Introduction to Solid State Physics, 8th ed., ch. 3: C11, C12, C44 in 1e11 N/m^2
KIT = {'W': (5.326, 2.049, 1.631), 'Cu': (1.684, 1.214, 0.754), 'Ag': (1.240, 0.937, 0.461), 'Au': (1.923, 1.631, 0.420),
       'Al': (1.068, 0.607, 0.282), 'diamond': (10.76, 1.25, 5.76), 'Si': (1.66, 0.64, 0.80),
       'Ge': (1.29, 0.48, 0.67), 'NaCl': (0.487, 0.124, 0.126), 'KCl': (0.40, 0.062, 0.0625), 'MgO': (2.86, 0.87, 1.48)}
born = all(c11 - c12 > 0 and c11 + 2 * c12 > 0 and c44 > 0 for c11, c12, c44 in KIT.values())
aniso = {k: 2 * c44 / (c11 - c12) for k, (c11, c12, c44) in KIT.items()}
span = max(v[0] for v in KIT.values()) / min(v[0] for v in KIT.values())
ok(f"EL4 Born stability holds for {len(KIT)} cubic crystals; C11 spans a factor {span:.0f}; anisotropy 2C44/(C11-C12) from "
   f"{min(aniso.values()):.2f} ({min(aniso, key=aniso.get)}) to {max(aniso.values()):.2f} ({max(aniso, key=aniso.get)}): the symmetry fixes "
   "three moduli, not their values", born and span > 20 and min(aniso.values()) < 0.6 and max(aniso.values()) > 2.5)

# ---------- EL5 Cauchy relation ----------
dev = {k: abs(c12 / c44 - 1) for k, (c11, c12, c44) in KIT.items()}
ok("EL5 Cauchy ratio C12/C44 - 1: " + ", ".join(f"{k} {KIT[k][1] / KIT[k][2] - 1:+.2f}" for k in ['NaCl', 'KCl', 'Cu', 'Au', 'Si', 'MgO']) +
   "; holds for the ionic crystals, fails for the others: not a consequence of the symmetry",
   dev['NaCl'] < 0.05 and dev['KCl'] < 0.05 and all(dev[k] > 0.15 for k in ['Cu', 'Au', 'Si', 'MgO']))

print("ALL PASS")
